/// <summary>
/// Extension class for CustInvoiceTable.
/// Automatically populates the Customer Reference field from CustTable.AGRCustomerReference
/// when a customer account is selected or changed on the Free Text Invoice header.
/// </summary>
[ExtensionOf(tableStr(CustInvoiceTable))]
final class CustInvoiceTable_AGR_Extension
{
}

Method.Source:
/// <summary>
/// Overrides modifiedField to populate CustomerRef from CustTable.AGRCustomerReference
/// whenever the customer account field is changed on the Free Text Invoice header.
/// </summary>
/// <param name="_fieldId">The ID of the field that was modified.</param>
public void modifiedField(FieldId _fieldId)
{
	next modifiedField(_fieldId);

	if (_fieldId == fieldNum(CustInvoiceTable, CustAccount))
	{
		CustTable custTable = CustTable::find(this.CustAccount);

		if (custTable)
		{
			this.CustomerRef = custTable.AGRCustomerReference;
		}
	}
}
